const choice=(id,use,context,answer,why,wrong)=>lessonChoice(id,use,context,[answer,...Object.keys(wrong)],[answer],why,wrong);
const transform=(id,use,context,source,answer,translation,why,wrong)=>lessonTransform(id,use,context,source,'',[answer,...Object.keys(wrong)],[answer],translation,why,wrong);

